import { env } from "cloudflare:workers";
import { comparison, validate, type Reading } from "./core";
export function db(){if(!env.DB)throw new Error("storage_unavailable");return env.DB;}
export async function load(scope:string){const result=await db().prepare("SELECT * FROM readings WHERE scope=? ORDER BY date DESC").bind(scope).all<any>(); const daily=result.results.map((row:any)=>({record_id:row.id,first_fetched_at:row.first_fetched,last_fetched_at:row.last_fetched,reading:JSON.parse(row.reading),raw:JSON.parse(row.raw)}));const status=await db().prepare("SELECT * FROM statuses WHERE scope=?").bind(scope).first<any>();return {daily_readings:daily,current_reading:daily[0]?.reading??null,status:status?{freshness:status.freshness,error_code:status.error,attempted_at:status.attempted,retry_after_seconds:status.retry_after}:null,last_comparison:comparison(daily.map((r:any)=>r.reading))};}
export async function success(scope:string,r:Reading,raw:any){validate(r);const binding=db(); await binding.batch([
 binding.prepare(`INSERT INTO readings(scope,signal,date,id,value,unit,reading,raw,first_fetched,last_fetched) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(scope,signal,date) DO UPDATE SET value=excluded.value,unit=excluded.unit,reading=excluded.reading,raw=excluded.raw,last_fetched=excluded.last_fetched WHERE excluded.last_fetched >= readings.last_fetched`).bind(scope,r.signal_id,r.record_date,`${scope}-${r.signal_id}-${r.record_date}`,r.normalized_value,r.unit,JSON.stringify(r),JSON.stringify(raw),r.fetched_at,r.fetched_at),
 binding.prepare("INSERT INTO statuses(scope,freshness,error,attempted,retry_after) VALUES(?,?,?,?,NULL) ON CONFLICT(scope) DO UPDATE SET freshness=excluded.freshness,error=excluded.error,attempted=excluded.attempted,retry_after=NULL WHERE excluded.attempted >= statuses.attempted").bind(scope,"fresh","none",r.fetched_at)
 ]);return load(scope);}
export async function failure(scope:string,error:string,now:string,retry:number|null=null){await db().prepare("INSERT INTO statuses(scope,freshness,error,attempted,retry_after) VALUES(?,?,?,?,?) ON CONFLICT(scope) DO UPDATE SET freshness=excluded.freshness,error=excluded.error,attempted=excluded.attempted,retry_after=excluded.retry_after").bind(scope,"stale",error,now,retry).run();return load(scope);}
export async function reset(scope:string){await db().batch([db().prepare("DELETE FROM readings WHERE scope=?").bind(scope),db().prepare("DELETE FROM statuses WHERE scope=?").bind(scope)]);return load(scope);}

lib/connector-contract.mts:
export type Json =
  | null
  | boolean
  | number
  | string
  | Json[]
  | { [key: string]: Json };

export type ConnectorFailureStatus =
  | "invalid_request"
  | "request_context_expired"
  | "reauthentication_required"
  | "connector_access_disabled"
  | "tool_not_found"
  | "tool_not_allowed"
  | "rate_limited"
  | "tool_error"
  | "upstream_error"
  | "internal_error"
  // Starter-only: no runtime capability or active local preview session.
  | "binding_unavailable";

export type ConnectorContent = {
  content: Array<{ type: string; [key: string]: Json }>;
  structuredContent?: Json;
};

// Matches Sites Dispatch's explicit invocation outcome, plus binding_unavailable.
export type ConnectorResult =
  | {
      status: "success";
      result: ConnectorContent;
      requestId?: string;
    }
  | {
      status: ConnectorFailureStatus;
      message: string;
      requestId?: string;
      retryAfterMs?: number;
      result?: ConnectorContent;
    };

/** A server-side binding supplied by the runtime, never by a browser. */
export type ConnectorBinding = {
  invoke(
    connectorId: string,
    actionName: string,
    args: { [key: string]: Json },
  ): Promise<ConnectorResult>;
  getContext?(): Promise<ConnectorContext>;
};

/** Site policy and cached tool metadata, not authentication or provider health. */
export type ConnectorContext =
  | {
      status: "success";
      connectors: Array<{
        connectorId: string;
        policy: "enabled" | "disabled";
        tools: Array<{
          actionName: string;
          description?: string;
          inputSchema: Record<string, Json>;
        }> | null;
      }>;
    }
  | {
      status:
        | "request_context_expired"
        | "internal_error"
        | "binding_unavailable"
        | "upstream_error";
    };

/** Use in a Site server route. Connection selection and credentials stay in the host. */
export function createConnectors(binding: ConnectorBinding | undefined) {
  return {
    async getContext(): Promise<ConnectorContext> {
      if (typeof window !== "undefined") {
        throw new Error(
          "Connected apps are only available in Site server routes.",
        );
      }
      try {
        if (!binding?.getContext) return { status: "binding_unavailable" };
        const context = await binding.getContext();
        if (
          context?.status === "success" &&
          Array.isArray(context.connectors)
        ) {
          return {
            status: "success",
            connectors: context.connectors.map((connector) => {
              if (
                !connector ||
                typeof connector.connectorId !== "string" ||
                !["enabled", "disabled"].includes(connector.policy) ||
                (connector.tools !== null && !Array.isArray(connector.tools))
              ) {
                throw new Error("Invalid connector context");
              }
              return {
                connectorId: connector.connectorId,
                policy: connector.policy,
                tools:
                  connector.tools?.map((tool) => {
                    if (
                      !tool ||
                      typeof tool.actionName !== "string" ||
                      (tool.description !== undefined &&
                        typeof tool.description !== "string") ||
                      !tool.inputSchema ||
                      typeof tool.inputSchema !== "object" ||
                      Array.isArray(tool.inputSchema)
                    ) {
                      throw new Error("Invalid connector tool");
                    }
                    return {
                      actionName: tool.actionName,
                      ...(tool.description !== undefined
                        ? { description: tool.description }
                        : {}),
                      inputSchema: tool.inputSchema,
                    };
                  }) ?? null,
              };
            }),
          };
        }
        switch (context?.status) {
          case "request_context_expired":
          case "internal_error":
          case "binding_unavailable":
          case "upstream_error":
            return { status: context.status };
          default:
            return { status: "upstream_error" };
        }
      } catch {
        return { status: "upstream_error" };
      }
    },
    async invoke(
      connectorId: string,
      actionName: string,
      args: { [key: string]: Json },
    ): Promise<ConnectorResult> {
      if (typeof window !== "undefined") {
        throw new Error(
          "Connected apps are only available in Site server routes.",
        );
      }
      if (!binding) {
        return {
          status: "binding_unavailable",
          message:
            "This runtime does not provide connected apps for this request.",
        };
      }
      try {
        // Preserve the host's status, message, result and optional diagnostics.
        // Do not replay a call after a transport failure: it may have completed.
        return await binding.invoke(connectorId, actionName, args);
      } catch {
        return {
          status: "upstream_error",
          message:
            "The app did not return a confirmed result. The action may have completed; check before trying again.",
        };
      }
    },
  };
}

